def links(items):
    def target(url):
        return 'https://github.com/LlewynLune/ai-portfolio/blob/main/'+url if url.endswith('.md') and '://' not in url else url
    return '<div class="item-links">'+''.join('<a href="'+target(url)+'">'+icon(k)+E(text)+'</a>' for k,text,url in items)+'</div>'

